  Nje = `Нулиране към наследено`,
  Pje = `Преименуване на команда`,
  Fje = `Преименуване на командна група`,
  Ije = `Изтриване на всички команди`,
  Lje = `Редактиране на времето за множествено обвързване`,
  Rje = `Настройване на времето`,
  zje = `Множествените обвързвания могат да бъдат визуализирани и настройвани в специализирания екран на редактора.`,
  Bje = `Разширяване`,
  Vje = `Свиване`,
  Hje = `%1$s (%2$s)`,
  Uje = `Време за множествено обвързване`,
  Wje = `Всяка лента представлява една команда, изпращана от този контрол при едно натискане. Времената са в милисекунди. Преместете манипулаторите за началото и края на лентата, за да промените кога да се задейства командата и кога да се освободи.`,
  Gje = `Хронология`,
  Kje = `Команди`,
  qje = `Натиснете`,
  Jje = `Отпускане`,
  Yje = `Продължителност на симулирано натискане на бутон`,
  Xje = `Колко дълго се задържа натискането в този предварителен преглед. Командите, които реагират на отпускането, се преместват в съответствие с него.`,
  Zje = `%1$s милисек.`,
  Qje = `+%1$s милисек.`,
  $je = `Задействане`,
  eMe = `Край`,
  tMe = `Стартиране`,
  nMe = `Приключване`,
  rMe = `%1$s%`,
  iMe = `Натискането трябва да продължи най-малко %1$s, за да се активира това.`,
  aMe = `%1$s се активира при това натискане, а тази команда е зададена да бъде прекъсваема, затова се пропуска.`,
  oMe = `Този контрол генерира само една команда, така че няма нужда от задаване на време между командите. Забавянията му все пак са изброени по-долу.`,
  sMe = `Пренареждане на въвежданията по стартово време`,
  cMe = `Сортиране`,
  lMe = `Безименно множествено обвързване`,
  uMe = `Необвързани`,
  dMe = `Мишка`,
