  Kct = `Допир`,
  qct = `Тази команда ще бъде изпълнена, когато докоснете пада/стика.`,
  Jct = `Команда от списък за скролиране — 1`,
  Yct = `Можете да възложите бутон или клавиш, който да бъде изпращан към играта при достигането на първия елемент.`,
  Xct = `Команда от списък за скролиране — 2`,
  Zct = `Можете да възложите бутон или клавиш, който да бъде изпращан към играта при достигането на втория елемент.`,
  Qct = `Команда от списък за скролиране — 3`,
  $ct = `Можете да възложите бутон или клавиш, който да бъде изпращан към играта при достигането на третия елемент.`,
  elt = `Команда от списък за скролиране — 4`,
  tlt = `Можете да възложите бутон или клавиш, който да бъде изпращан към играта при достигането на четвъртия елемент.`,
  nlt = `Команда от списък за скролиране — 5`,
